fn register_functions<'lua>(
    mut builder: TableBuilder<'lua>,
    functions: &[(&str, RustFn)],
) -> LuaResult<TableBuilder<'lua>> {
    for (name, func) in functions {
        builder = builder.set_function(name, *func)?;
    }
    Ok(builder)
}

