fn set_frame_protected(state: &mut LuaState) -> LuaResult<u32> {
    let name = String::from_stack(state, 1)?;
    let v = bool::from_stack(state, 2)?;
    let mut st = borrow_state_mut(state)?;
    if let Some(id) = st.widgets.get_id_by_name(&name)
        && let Some(frame) = st.widgets.get_mut(id)
    {
        frame.is_protected = v;
    }
    Ok(0)
}

// ── Casting & cooldowns ──────────────────────────────────────────────────────

fn set_casting(state: &mut LuaState) -> LuaResult<u32> {
    let spell_id = u32::from_stack(state, 1)?;
    let spell_name = String::from_stack(state, 2)?;
    let icon_path = String::from_stack(state, 3)?;
    let duration = f64::from_stack(state, 4)?;
    let mut st = borrow_state_mut(state)?;
    let now = st.start_time.elapsed().as_secs_f64();
    let cast_id = st.next_cast_id;
    st.next_cast_id += 1;
    #[cfg(feature = "player-cast-durations")]
    crate::lua_api::spellcast_events::clear_replaced_specialization(&mut st);
    st.casting = Some(CastingState {
        spell_id,
        spell_name,
        icon_path,
        start_time: now,
        end_time: now + duration,
        cast_id,
        empower: None,
        delay_time: 0.0,
    });
    drop(st);
    #[cfg(feature = "player-cast-durations")]
    crate::lua_api::channeling::cancel_for_cast(state)?;
    Ok(0)
}

fn stop_casting(state: &mut LuaState) -> LuaResult<u32> {
    borrow_state_mut(state)?.casting = None;
    Ok(0)
}

fn set_gcd(state: &mut LuaState) -> LuaResult<u32> {
    let duration = f64::from_stack(state, 1)?;
    let mut st = borrow_state_mut(state)?;
    let now = st.start_time.elapsed().as_secs_f64();
    st.gcd = Some((now, duration));
    Ok(0)
}

fn set_spell_cooldown(state: &mut LuaState) -> LuaResult<u32> {
    let spell_id = u32::from_stack(state, 1)?;
    let duration = f64::from_stack(state, 2)?;
    let mut st = borrow_state_mut(state)?;
    let now = st.start_time.elapsed().as_secs_f64();
    st.spell_cooldowns.insert(
        spell_id,
        SpellCooldownState {
            start: now,
            duration,
        },
    );
    Ok(0)
}

// ── Health & power ───────────────────────────────────────────────────────────

fn set_player_health(state: &mut LuaState) -> LuaResult<u32> {
    let cur = i32::from_stack(state, 1)?;
    let max = i32::from_stack(state, 2)?;
    let mut st = borrow_state_mut(state)?;
    st.player.health = cur;
    st.player.health_max = max;
    Ok(0)
}

fn set_player_power(state: &mut LuaState) -> LuaResult<u32> {
    let cur = i32::from_stack(state, 1)?;
    let max = i32::from_stack(state, 2)?;
    let power_type = Option::<i32>::from_stack(state, 3)?;
    let mut st = borrow_state_mut(state)?;
    if let Some(pt) = power_type {
        if is_secondary_player_power_type(pt) {
            st.player
                .secondary_powers
                .insert(pt, SecondaryPowerState { current: cur, max });
            return Ok(0);
        }
        st.player.power_type = pt;
    }
    st.player.power = cur;
    st.player.power_max = max;
    Ok(0)
}

fn is_secondary_player_power_type(power_type: i32) -> bool {
    matches!(
        power_type,
        4 | 5 | 6 | 7 | 8 | 9 | 11 | 12 | 13 | 16 | 17 | 18
    )
}

fn set_target_health(state: &mut LuaState) -> LuaResult<u32> {
    let cur = i32::from_stack(state, 1)?;
    let max = i32::from_stack(state, 2)?;
    let mut st = borrow_state_mut(state)?;
    if let Some(t) = st.current_target.as_mut() {
        t.health = cur;
        t.health_max = max;
    }
    Ok(0)
}

// ── Internal helpers ──────────────────────────────────────────────────────────

/// Build an AuraInfo for admin-added buffs.
pub(super) fn build_admin_buff(
    st: &crate::lua_api::state::SimState,
    spell_id: i32,
    name: String,
    icon: String,
    duration: f64,
    stacks: i32,
) -> AuraInfo {
    build_admin_aura(st, spell_id, name, icon, duration, stacks, true, None)
}

/// Build an AuraInfo for admin-added auras (buffs or debuffs).
#[allow(clippy::too_many_arguments)]
pub(super) fn build_admin_aura(
    st: &crate::lua_api::state::SimState,
    spell_id: i32,
    name: String,
    icon: String,
    duration: f64,
    stacks: i32,
    is_helpful: bool,
    dispel_type: Option<String>,
) -> AuraInfo {
    let expiration_time = if duration > 0.0 {
        st.start_time.elapsed().as_secs_f64() + duration
    } else {
        0.0
    };
    AuraInfo {
        name,
        spell_id,
        icon: icon.parse::<i32>().unwrap_or(0),
        duration,
        expiration_time,
        applications: stacks,
        source_unit: "player".to_string(),
        is_helpful,
        is_stealable: false,
        can_apply_aura: is_helpful,
        is_from_player_or_player_pet: is_helpful,
        dispel_type,
        aura_instance_id: (st.player.buffs.len() + 1) as i32,
    }
}

/// Build a MailMessage for admin inbox functions.
pub(crate) fn build_mail(
    id: u64,
    sender: String,
    subject: String,
    body: String,
    money: u64,
    items: Vec<crate::lua_api::state_types::MailAttachment>,
) -> crate::lua_api::state_types::MailMessage {
    crate::lua_api::state_types::MailMessage {
        id,
        sender,
        subject,
        body,
        money,
        cod_amount: 0,
        items,
        days_left: 30.0,
        was_read: false,
        was_returned: false,
        can_reply: true,
        is_gm: false,
        stationery_icon: 0,
    }
}

/// Extract a string from the stack, returning a default if nil or absent.
pub(super) fn opt_string_stack(state: &LuaState, index: i32, default: &str) -> String {
    match crate::lua_bridge::stack_val(state, index) {
        Val::Str(s) => state
            .gc
            .string_arena
            .get(s)
            .map(|ls| String::from_utf8_lossy(ls.data()).into_owned())
            .unwrap_or_else(|| default.to_string()),
        _ => default.to_string(),
    }
}
